function sanitizeUploadFilename(name){var lastDot=name.lastIndexOf(".");var base=(lastDot>-1)?name.substring(0,lastDot):name;var ext=(lastDot>-1)?name.substring(lastDot):"";base=base.replace(/[^A-Za-z0-9\-_ ]/g,"").replace(/\s+/g,"-");if(base==="")base="file";return base+ext;}
Dropzone.options.uploadWidget={paramName:"file",maxFilesize:10,dictDefaultMessage:"Drag files here to upload. Or, click here to select from your files.",dictFileTooBig:"Image size is too big. Maximum size is 10mb.",acceptedFiles:".jpeg,.jpg,.png,.gif,.JPEG,.JPG,.PNG,.GIF,.PDF,.pdf,.svg,.SVG,.webp,.WEBP",init:function(){this.on("addedfile",function(file){var cleanName=sanitizeUploadFilename(file.name);if(cleanName!==file.name){try{Object.defineProperty(file,"name",{value:cleanName,configurable:true});}catch(e){}}}).on("queuecomplete",function(e){location.reload()})}};
